// Regression: prices with thousands separators (e.g. "1,299.00") crashed POST /checkout with a 500.
const assert = require('assert');
const { parseAmount } = require('../src/money');
const { handle } = require('../src/server');

test('parses amounts with thousands separators', () => {
  assert.strictEqual(parseAmount('1,299.00'), 129900);
  assert.strictEqual(parseAmount('2,450.50'), 245050);
  assert.strictEqual(parseAmount('1,000,000'), 100000000);
});

test('rejects malformed amounts with a descriptive error', () => {
  for (const bad of ['', 'abc', '1,29.00', '12,', '1.234', null]) {
    assert.throws(() => parseAmount(bad), /^Error: Invalid amount: /);
  }
});

test('POST /checkout with a thousands-separated price returns 200', () => {
  const log = console.log;
  console.log = () => {};
  let res;
  try {
    res = handle({ method: 'POST', path: '/checkout', body: { id: 'ord_10135', items: [{ sku: 'P-92', price: '1,299.00', qty: 3 }] } });
  } finally {
    console.log = log;
  }
  assert.strictEqual(res.status, 200);
  assert.deepStrictEqual(res.body, { orderId: 'ord_10135', totalCents: 389700 });
});

